/**
 * Differential tester: runs the reference executable and the Node port with
 * identical argv and compares stdout, stderr and exit status.
 *
 * The bootloader's `[PYI-<pid>:ERROR]` line embeds the live process id, so that
 * number is normalised before comparison. Nothing else is masked.
 *
 * Usage:
 *   node difftest.mjs            # run the built-in battery
 *   node difftest.mjs -- ARG...  # compare one explicit argv
 */

import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';

function normalize(text) {
  return text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function runCase(argv, env) {
  const options = { encoding: 'utf8', env: { ...process.env, ...env } };
  const reference = spawnSync(REFERENCE, argv, options);
  const port = spawnSync('node', [PORT, ...argv], options);
  return {
    argv,
    env,
    ok:
      normalize(reference.stdout ?? '') === normalize(port.stdout ?? '')
      && normalize(reference.stderr ?? '') === normalize(port.stderr ?? '')
      && reference.status === port.status,
    reference: {
      stdout: reference.stdout, stderr: reference.stderr, status: reference.status,
    },
    port: { stdout: port.stdout, stderr: port.stderr, status: port.status },
  };
}

/** Argv vectors covering success, lookup failure and every argparse misuse. */
const CASES = [
  // documented samples
  ['--key', 'a', '--val', '83'],
  ['--key', 'a', '--val', '97'],
  ['--key', 'b', '--val', '21'],
  ['--key', 'b', '--val', '53'],
  // lookup failures
  ['--key', 'c', '--val', '1'],
  ['--key', 'A', '--val', '1'],
  ['--key', '', '--val', '1'],
  ['--key', '1', '--val', '1'],
  ['--key', '2', '--val', '1'],
  ['--key', 'ab', '--val', '1'],
  // repr-sensitive keys
  ["--key", "a'b", '--val', '1'],
  ['--key', 'a"b', '--val', '1'],
  ['--key', 'a\'b"c', '--val', '1'],
  ['--key', 'a\\b', '--val', '1'],
  ['--key', 'a\tb', '--val', '1'],
  ['--key', 'a\nb', '--val', '1'],
  ['--key', '\x01', '--val', '1'],
  ['--key', '\x7f', '--val', '1'],
  ['--key', 'é', '--val', '1'],
  ['--key', '中', '--val', '1'],
  ['--key', '😀', '--val', '1'],
  ['--key', '­', '--val', '1'],
  ['--key', ' ', '--val', '1'],
  ['--key', '​', '--val', '1'],
  ['--key', ' ', '--val', '1'],
  ['--key', 'a b', '--val', '1'],
  ['--key', 'True', '--val', '1'],
  ['--key', 'None', '--val', '1'],
  // missing / required
  [],
  ['--val', '5'],
  ['--key', 'a'],
  ['--key'],
  ['--val'],
  ['--key', '--val', '5'],
  ['--key', 'a', '--val'],
  // help
  ['--help'],
  ['-h'],
  ['--h'],
  ['--he'],
  ['--hel'],
  ['-h', '--key', 'a'],
  ['--key', 'a', '--val', '1', '-h'],
  // abbreviation and equals forms
  ['--key=a', '--val=83'],
  ['--k', 'a', '--v', '1'],
  ['--ke', 'a', '--va', '1'],
  ['--k=a', '--v=1'],
  ['--key=', '--val='],
  ['--key=a=b', '--val', '1'],
  // unrecognized / extras
  ['--key', 'a', '--val', '83', 'extra'],
  ['--key', 'a', '--val', '83', '--bogus', '5'],
  ['--key', 'a', '--val', '1', '-1'],
  ['--key', 'a', '--val', '1', '-'],
  ['-', '--key', 'a', '--val', '1'],
  ['--key', 'a', 'b', '--val', '1'],
  ['--keyy', 'a', '--val', '1'],
  ['-k', 'a', '-v', '1'],
  ['--key', 'a', '--bogus'],
  ['--bogus', '--key', 'a', '--val', '1'],
  // repeated options
  ['--key', 'a', '--key', 'b', '--val', '1'],
  ['--key', 'b', '--key', 'a', '--val', '1'],
  ['--key', 'a', '--val', '1', '--val', '2'],
  ['--key', '--key', '--val', '1'],
  // dash-dash handling
  ['--', '--key', 'a', '--val', '1'],
  ['--key', 'a', '--val', '1', '--'],
  ['--key', 'a', '--', '--val', '1'],
  ['--key', '--', '--val', '1'],
  ['--key', 'a', '--val', '1', '--', 'extra'],
  ['--key=a', '--val=1', '--'],
  ['--', '--'],
  // negative-number-looking values
  ['--key', '-1', '--val', '1'],
  ['--key=-1', '--val', '1'],
  ['--key', '-1.5', '--val', '1'],
  ['--key', '-x', '--val', '1'],
  ['--key', '-1a', '--val', '1'],
  // ordering
  ['--val', '83', '--key', 'a'],
  ['--val=83', '--key=b'],
];

/** Widths that exercise every branch of the usage/help wrapper. */
const WIDTH_ENVS = [
  {}, { COLUMNS: '20' }, { COLUMNS: '24' }, { COLUMNS: '30' }, { COLUMNS: '34' },
  { COLUMNS: '38' }, { COLUMNS: '44' }, { COLUMNS: '48' }, { COLUMNS: '50' },
  { COLUMNS: '60' }, { COLUMNS: '80' }, { COLUMNS: '120' }, { COLUMNS: '11' },
  { COLUMNS: '1' }, { COLUMNS: '0' }, { COLUMNS: 'abc' }, { COLUMNS: '-5' },
];

function main() {
  const explicit = process.argv.indexOf('--');
  if (explicit !== -1) {
    const result = runCase(process.argv.slice(explicit + 1), {});
    console.log(JSON.stringify(result, null, 2));
    process.exit(result.ok ? 0 : 1);
  }

  const failures = [];
  let total = 0;

  for (const argv of CASES) {
    total += 1;
    const result = runCase(argv, {});
    if (!result.ok) failures.push(result);
  }

  // Width sensitivity only shows up on the paths that print usage or help.
  const widthCases = [['--help'], [], ['--val', '5'], ['--key', 'a', '--val', '1', 'extra']];
  for (const env of WIDTH_ENVS) {
    for (const argv of widthCases) {
      total += 1;
      const result = runCase(argv, env);
      if (!result.ok) failures.push(result);
    }
  }

  for (const failure of failures) {
    console.log(`FAIL argv=${JSON.stringify(failure.argv)} env=${JSON.stringify(failure.env)}`);
    console.log(`  ref  status=${failure.reference.status}`);
    console.log(`  port status=${failure.port.status}`);
    if (failure.reference.stdout !== failure.port.stdout) {
      console.log(`  ref  stdout=${JSON.stringify(failure.reference.stdout)}`);
      console.log(`  port stdout=${JSON.stringify(failure.port.stdout)}`);
    }
    if (normalize(failure.reference.stderr) !== normalize(failure.port.stderr)) {
      console.log(`  ref  stderr=${JSON.stringify(failure.reference.stderr)}`);
      console.log(`  port stderr=${JSON.stringify(failure.port.stderr)}`);
    }
  }

  console.log(`\n${total - failures.length}/${total} cases identical`);
  process.exit(failures.length === 0 ? 0 : 1);
}

main();

