/**
 * Mirrors `shutil.get_terminal_size()`, which argparse consults to pick a help
 * width.
 *
 * CPython honours the COLUMNS/LINES environment variables first, then queries
 * the real terminal attached to stdout, then falls back to (80, 24).
 */

const FALLBACK_COLUMNS = 80;
const FALLBACK_LINES = 24;

/**
 * CPython uses `int(os.environ['COLUMNS'])`, which accepts surrounding
 * whitespace and an optional sign but rejects anything else. A ValueError (or a
 * non-positive result) makes it fall through to the next source.
 *
 * @param {string|undefined} raw
 * @returns {number} parsed value, or 0 when unusable
 */
function parseIntStrict(raw) {
  if (raw === undefined) return 0;
  const text = raw.trim();
  if (!/^[+-]?\d+$/.test(text)) return 0;
  return Number.parseInt(text, 10);
}

/**
 * @param {{columns?: number, lines?: number}} [fallback]
 * @returns {{columns: number, lines: number}}
 */
export function getTerminalSize(fallback = {}) {
  const fallbackColumns = fallback.columns ?? FALLBACK_COLUMNS;
  const fallbackLines = fallback.lines ?? FALLBACK_LINES;

  let columns = parseIntStrict(process.env.COLUMNS);
  let lines = parseIntStrict(process.env.LINES);

  if (columns <= 0 || lines <= 0) {
    // `os.get_terminal_size(sys.__stdout__.fileno())`; when stdout is not a
    // tty this raises OSError and CPython uses the fallback pair.
    const ttyColumns = process.stdout.isTTY ? process.stdout.columns : undefined;
    const ttyLines = process.stdout.isTTY ? process.stdout.rows : undefined;

    if (columns <= 0) columns = ttyColumns && ttyColumns > 0 ? ttyColumns : fallbackColumns;
    if (lines <= 0) lines = ttyLines && ttyLines > 0 ? ttyLines : fallbackLines;
  }

  return { columns, lines };
}

