/**
 * Width fuzzer: sweeps COLUMNS/LINES over the whole requested space for a set
 * of argv vectors, spawning the reference binary and the Node port directly so
 * we compare raw bytes.
 */
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';

const CONCURRENCY = Number(process.env.FUZZ_CONCURRENCY ?? 12);

function normalize(buf) {
  return buf.toString('utf8').replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');
}

function run(cmd, argv, env, cwd) {
  return new Promise((resolve) => {
    const child = spawn(cmd, argv, { env, cwd, stdio: ['ignore', 'pipe', 'pipe'] });
    const out = [];
    const err = [];
    child.stdout.on('data', (d) => out.push(d));
    child.stderr.on('data', (d) => err.push(d));
    child.on('error', (e) => resolve({ stdout: '', stderr: `SPAWN_ERROR ${e.message}`, status: null, signal: null }));
    child.on('close', (status, signal) => {
      resolve({
        stdout: Buffer.concat(out),
        stderr: Buffer.concat(err),
        status,
        signal,
      });
    });
  });
}

function buildEnv(envSpec) {
  const env = { ...process.env };
  delete env.COLUMNS;
  delete env.LINES;
  for (const [k, v] of Object.entries(envSpec)) {
    if (v === null) delete env[k];
    else env[k] = v;
  }
  return env;
}

async function runCase(c) {
  const env = buildEnv(c.env);
  const [ref, port] = await Promise.all([
    run(REFERENCE, c.argv, env, c.cwd),
    run(process.execPath, [PORT, ...c.argv], env, c.cwd),
  ]);
  const rOut = normalize(ref.stdout);
  const pOut = normalize(port.stdout);
  const rErr = normalize(ref.stderr);
  const pErr = normalize(port.stderr);
  const ok = rOut === pOut && rErr === pErr && ref.status === port.status && ref.signal === port.signal;
  return {
    ...c,
    ok,
    ref: { stdout: rOut, stderr: rErr, status: ref.status, signal: ref.signal },
    port: { stdout: pOut, stderr: pErr, status: port.status, signal: port.signal },
  };
}

async function pool(cases, worker) {
  const results = new Array(cases.length);
  let next = 0;
  let done = 0;
  const runners = [];
  for (let i = 0; i < Math.min(CONCURRENCY, cases.length); i += 1) {
    runners.push((async () => {
      while (true) {
        const idx = next;
        next += 1;
        if (idx >= cases.length) return;
        results[idx] = await worker(cases[idx]);
        done += 1;
        if (done % 100 === 0) process.stderr.write(`  ...${done}/${cases.length}\n`);
      }
    })());
  }
  await Promise.all(runners);
  return results;
}

// ---------------------------------------------------------------- case matrix

const ARGVS = [
  ['--help'],
  [],
  ['--val', '5'],
  ['--key', 'a'],
  ['--key', 'a', '--val', '1', 'extra'],
  ['--bogus'],
];

const COLUMNS_VALUES = [];
for (let w = 1; w <= 120; w += 1) COLUMNS_VALUES.push(String(w));
COLUMNS_VALUES.push(
  '0',
  '-1',
  '-5',
  '-80',
  '100000',
  '99999999999999999999',
  'abc',
  'wide',
  '40abc',
  'abc40',
  '  40  ',
  '\t40\t',
  '\n40\n',
  ' 40',
  '40 ',
  '+40',
  '-0',
  '4_0',
  '40.0',
  '40.',
  '0x28',
  '0b101000',
  '040',
  '',
  ' ',
  '\t',
  'NaN',
  'Infinity',
  'inf',
  '1e2',
  '  40  ', // NBSP-padded (Python int() rejects NBSP)
  ' 740', // odd unicode
  '４０', // fullwidth digits: Python int() accepts -> 40
  '٤٠', // arabic-indic digits: Python int() accepts -> 40
  '40\0', // embedded NUL truncates for execve-passed env
);

const LINES_VALUES = ['1', '2', '10', '24', '25', '1000', '0', '-1', 'abc', '', '  24  '];

const cases = [];

// 1. COLUMNS sweep (LINES unset), every argv.
for (const col of COLUMNS_VALUES) {
  for (const argv of ARGVS) {
    cases.push({ argv, env: { COLUMNS: col }, label: `COLUMNS=${JSON.stringify(col)}` });
  }
}

// 2. COLUMNS unset entirely, every argv.
for (const argv of ARGVS) {
  cases.push({ argv, env: {}, label: 'COLUMNS unset' });
}

// 3. LINES only (no COLUMNS), every argv.
for (const lines of LINES_VALUES) {
  for (const argv of ARGVS) {
    cases.push({ argv, env: { LINES: lines }, label: `LINES=${JSON.stringify(lines)} (no COLUMNS)` });
  }
}

// 4. LINES together with a spread of COLUMNS, every argv.
const COL_WITH_LINES = ['1', '2', '5', '11', '15', '20', '25', '30', '40', '55', '80', '120', '0', '-5', 'abc', '', '  40  ', '100000'];
for (const lines of LINES_VALUES) {
  for (const col of COL_WITH_LINES) {
    for (const argv of ARGVS) {
      cases.push({ argv, env: { COLUMNS: col, LINES: lines }, label: `COLUMNS=${JSON.stringify(col)} LINES=${JSON.stringify(lines)}` });
    }
  }
}

process.stderr.write(`total cases: ${cases.length}\n`);

const results = await pool(cases, runCase);
const failures = results.filter((r) => !r.ok);

writeFileSync('/tmp/fuzz/failures.json', JSON.stringify(failures, null, 2));
process.stderr.write(`\n${results.length - failures.length}/${results.length} identical; ${failures.length} divergences\n`);
for (const f of failures.slice(0, 40)) {
  process.stderr.write(`FAIL argv=${JSON.stringify(f.argv)} env=${JSON.stringify(f.env)}\n`);
  if (f.ref.stdout !== f.port.stdout) process.stderr.write(`  refOUT=${JSON.stringify(f.ref.stdout)}\n  potOUT=${JSON.stringify(f.port.stdout)}\n`);
  if (f.ref.stderr !== f.port.stderr) process.stderr.write(`  refERR=${JSON.stringify(f.ref.stderr)}\n  potERR=${JSON.stringify(f.port.stderr)}\n`);
  if (f.ref.status !== f.port.status) process.stderr.write(`  refST=${f.ref.status} potST=${f.port.status}\n`);
}

