/**
 * Width oracle: fingerprints `--help` output for every explicit COLUMNS in
 * 1..200 (reference and port separately), then reports, for an arbitrary
 * COLUMNS spelling, which numeric width each binary effectively resolved to.
 */
import { spawnSync } from 'node:child_process';

const REFERENCE = '/workspace/dataset/test2_executable';
const PORT = '/output/test2.mjs';

function help(cmd, argvPrefix, columns) {
  const env = { ...process.env };
  delete env.LINES;
  if (columns === null) delete env.COLUMNS;
  else env.COLUMNS = columns;
  const r = spawnSync(cmd, [...argvPrefix, '--help'], { env, encoding: 'utf8' });
  return r.stdout;
}

// Build fingerprint tables keyed by output text -> list of widths producing it.
const refTable = [];
const portTable = [];
for (let n = 1; n <= 200; n += 1) {
  refTable.push([n, help(REFERENCE, [], String(n))]);
  portTable.push([n, help(process.execPath, [PORT], String(n))]);
}

function resolve(table, text) {
  const hits = table.filter(([, t]) => t === text).map(([n]) => n);
  if (hits.length === 0) return 'unknown';
  if (hits.length === 1) return String(hits[0]);
  return `${hits[0]}..${hits[hits.length - 1]}`;
}

const PROBES = process.argv.slice(2).length
  ? JSON.parse(process.argv[2])
  : ['40', '4_0', '1_0_0', '\x1c40', '\x1d40', '\x1f40', '\x8540', '﻿40', '​40', 'abc', '', '４０', '٤٠', '၀၁'];

for (const v of PROBES) {
  const rt = help(REFERENCE, [], v);
  const pt = help(process.execPath, [PORT], v);
  const rw = resolve(refTable, rt);
  const pw = resolve(portTable, pt);
  const flag = rt === pt ? 'ok  ' : 'DIFF';
  console.log(`${flag} COLUMNS=${JSON.stringify(v)}  refWidth=${rw}  portWidth=${pw}`);
}

